<?php $editing = $product !== null; $errors = validation_errors(); $action = $editing ? site_url('products/' . $product['id']) : site_url('products'); ?>
<section class="page-banner compact"><div class="container page-banner-inner"><div><p class="eyebrow">CATALOG / <?= $editing ? 'EDIT' : 'NEW' ?></p><h1><?= $editing ? 'Edit product.' : 'Add a product.' ?></h1><p class="lead">The price and stock you save here are used when staff record a sale.</p></div><a class="text-link" href="<?= site_url('products') ?>">← Back to catalog</a></div></section>
<section class="section form-section"><div class="container narrow"><div class="form-card">
    <?php if ($errors !== []): ?><p class="form-alert" role="alert">Please check the highlighted fields.</p><?php endif; ?>
    <?php if (session('form_error')): ?><p class="form-alert" role="alert"><?= esc(session('form_error')) ?></p><?php endif; ?>
    <form method="post" action="<?= esc($action, 'attr') ?>" enctype="multipart/form-data"><?= csrf_field() ?>
        <div class="form-grid">
            <div class="form-field full-width"><label for="name">Product name <span class="required-mark">*</span></label><input id="name" name="name" maxlength="100" required value="<?= esc(old('name', $product['name'] ?? '', false), 'attr') ?>" placeholder="e.g. House Blend Coffee"><?php if (isset($errors['name'])): ?><p class="field-error"><?= esc($errors['name']) ?></p><?php endif; ?></div>
            <div class="form-field"><label for="price">Price (PHP) <span class="required-mark">*</span></label><input id="price" name="price" type="number" min="0.01" max="99999999.99" step="0.01" required value="<?= esc(old('price', $product['price'] ?? '', false), 'attr') ?>" placeholder="0.00"><?php if (isset($errors['price'])): ?><p class="field-error"><?= esc($errors['price']) ?></p><?php endif; ?></div>
            <div class="form-field"><label for="stock_quantity">Units in stock <span class="required-mark">*</span></label><input id="stock_quantity" name="stock_quantity" type="number" min="0" max="2147483647" step="1" required value="<?= esc(old('stock_quantity', $product['stock_quantity'] ?? '0', false), 'attr') ?>"><?php if (isset($errors['stock_quantity'])): ?><p class="field-error"><?= esc($errors['stock_quantity']) ?></p><?php endif; ?></div>
            <div class="form-field"><label for="is_active">Catalog status</label><select id="is_active" name="is_active" required><option value="1" <?= (string) old('is_active', $product['is_active'] ?? '1', false) === '1' ? 'selected' : '' ?>>Available for checkout</option><option value="0" <?= (string) old('is_active', $product['is_active'] ?? '1', false) === '0' ? 'selected' : '' ?>>Archived</option></select><?php if (isset($errors['is_active'])): ?><p class="field-error"><?= esc($errors['is_active']) ?></p><?php endif; ?></div>
        </div>
        <div class="upload-panel"><img src="<?= esc(marketmate_product_image_url($product['image'] ?? null), 'attr') ?>" alt="<?= $editing ? 'Current product picture' : 'Product picture placeholder' ?>"><div class="form-field"><label for="image"><?= $editing ? 'Replace product picture' : 'Product picture' ?></label><input id="image" name="image" type="file" accept="image/jpeg,image/png" aria-describedby="image-help"><p class="field-help" id="image-help">Optional JPG or PNG, up to 3 MB. MarketMate prepares an 800 × 600 display image.</p><?php if (isset($errors['image'])): ?><p class="field-error"><?= esc($errors['image']) ?></p><?php endif; ?></div></div>
        <div class="form-actions"><button class="button primary" type="submit"><?= $editing ? 'Save product' : 'Add to catalog' ?></button><a class="button secondary" href="<?= site_url('products') ?>">Cancel</a></div>
    </form>
</div></div></section>
